/**
 * Kilocode Provider Extension
 *
 * Registers Kilo.ai as a Pi provider, giving access to 500+ models via the
 * Kilo Gateway (OpenRouter-compatible). Supports device-code OAuth login.
 *
 * Usage:
 *   /login kilo          — authenticate via browser device flow
 *   /logout kilo         — clear stored credentials
 *   Set KILO_API_KEY env var to skip OAuth and use a static key
 */

import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import type {
  Api,
  Model,
  OAuthCredentials,
  OAuthLoginCallbacks,
} from "@valkyriweb/pi-ai";
import type { ExtensionAPI, ProviderModelConfig } from "@valkyriweb/pi-coding-agent";
import { Effect } from "effect";

// ─── Constants ───────────────────────────────────────────────────────────────

const KILO_API_BASE = process.env.KILO_API_URL ?? "https://api.kilo.ai";
const KILO_GATEWAY_BASE = `${KILO_API_BASE}/api/gateway`;
const KILO_DEVICE_AUTH = `${KILO_API_BASE}/api/device-auth/codes`;
const KILO_PROFILE = `${KILO_API_BASE}/api/profile`;
const KILO_TOS_URL = "https://kilo.ai/terms";
const POLL_INTERVAL_MS = 3_000;
const MODELS_TIMEOUT_MS = 10_000;
const TOKEN_TTL_MS = 365 * 24 * 60 * 60 * 1_000;

const PROVIDER_CONFIG = {
  baseUrl: KILO_GATEWAY_BASE,
  apiKey: "$KILO_API_KEY",
  api: "openai-completions" as const,
  headers: {
    "X-KILOCODE-EDITORNAME": "Pi",
    "User-Agent": "pi-kilocode-provider/1.0",
  },
};

interface KiloFetchOptions extends RequestInit {
  readonly timeoutMs?: number;
}

class KiloRequestError extends Error {
  readonly _tag = "KiloRequestError";
  readonly cause: unknown;

  constructor(cause: unknown) {
    super(cause instanceof Error ? cause.message : String(cause));
    this.name = "KiloRequestError";
    this.cause = cause;
  }
}

function fetchKilo(input: string, options: KiloFetchOptions = {}): Promise<Response> {
  return Effect.runPromise(kiloRequest(input, options));
}

function kiloRequest(input: string, options: KiloFetchOptions): Effect.Effect<Response, KiloRequestError> {
  const { timeoutMs, signal, ...init } = options;
  return Effect.tryPromise({
    try: () => fetch(input, { ...init, signal: requestSignal(signal, timeoutMs) }),
    catch: (cause) => new KiloRequestError(cause),
  });
}

function requestSignal(signal: AbortSignal | null | undefined, timeoutMs: number | undefined): AbortSignal | undefined {
  if (!timeoutMs) return signal ?? undefined;
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  return signal ? AbortSignal.any([signal, timeoutSignal]) : timeoutSignal;
}

// ─── Balance ─────────────────────────────────────────────────────────────────

async function fetchBalance(token: string): Promise<number | null> {
  try {
    const r = await fetchKilo(`${KILO_PROFILE}/balance`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!r.ok) return null;
    const data = (await r.json()) as { balance?: number };
    return data.balance ?? null;
  } catch {
    return null;
  }
}

function formatCredits(n: number): string {
  return n >= 1000 ? `$${(n / 1000).toFixed(1)}k` : `$${n.toFixed(2)}`;
}

function loadStoredToken(): string | undefined {
  try {
    const path = join(homedir(), ".pi", "agent", "auth.json");
    if (!existsSync(path)) return undefined;
    const json = JSON.parse(readFileSync(path, "utf8")) as {
      kilo?: { type?: string; access?: string; expires?: number };
    };
    const cred = json.kilo;
    if (cred?.type !== "oauth") return undefined;
    if (!cred.access || (typeof cred.expires === "number" && cred.expires <= Date.now())) return undefined;
    return cred.access;
  } catch {
    return undefined;
  }
}

// ─── OAuth / Device-Code Flow ─────────────────────────────────────────────────

interface DeviceAuthResponse {
  code: string;
  verificationUrl: string;
  expiresIn: number;
}

interface PollResponse {
  status: "pending" | "approved" | "denied" | "expired";
  token?: string;
}

async function initiateDeviceAuth(): Promise<DeviceAuthResponse> {
  const r = await fetchKilo(KILO_DEVICE_AUTH, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
  });
  if (!r.ok) {
    if (r.status === 429) throw new Error("Too many pending requests — try again shortly.");
    throw new Error(`Device auth failed: ${r.status}`);
  }
  return r.json() as Promise<DeviceAuthResponse>;
}

async function pollDeviceAuth(code: string): Promise<PollResponse> {
  const r = await fetchKilo(`${KILO_DEVICE_AUTH}/${code}`);
  if (r.status === 202) return { status: "pending" };
  if (r.status === 403) return { status: "denied" };
  if (r.status === 410) return { status: "expired" };
  if (!r.ok) throw new Error(`Poll failed: ${r.status}`);
  return r.json() as Promise<PollResponse>;
}

function abortSleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) { reject(new Error("Cancelled")); return; }
    const t = setTimeout(resolve, ms);
    signal?.addEventListener("abort", () => { clearTimeout(t); reject(new Error("Cancelled")); }, { once: true });
  });
}

async function kiloLogin(callbacks: OAuthLoginCallbacks): Promise<OAuthCredentials> {
  callbacks.onProgress?.("Starting device authorisation…");
  const { code, verificationUrl, expiresIn } = await initiateDeviceAuth();

  callbacks.onAuth({ url: verificationUrl, instructions: `Enter code: ${code}` });
  callbacks.onProgress?.("Waiting for browser authorisation…");

  const deadline = Date.now() + expiresIn * 1_000;
  while (Date.now() < deadline) {
    if (callbacks.signal?.aborted) throw new Error("Login cancelled");
    await abortSleep(POLL_INTERVAL_MS, callbacks.signal);

    const result = await pollDeviceAuth(code);
    if (result.status === "approved") {
      if (!result.token) throw new Error("Approved but no token received");
      callbacks.onProgress?.("Login successful!");
      return { refresh: result.token, access: result.token, expires: Date.now() + TOKEN_TTL_MS };
    }
    if (result.status === "denied")  throw new Error("Authorisation denied.");
    if (result.status === "expired") throw new Error("Code expired — please try again.");

    const secs = Math.ceil((deadline - Date.now()) / 1_000);
    callbacks.onProgress?.(`Waiting… (${secs}s remaining)`);
  }
  throw new Error("Authentication timed out.");
}

async function kiloRefresh(cred: OAuthCredentials): Promise<OAuthCredentials> {
  if (cred.expires > Date.now()) return cred;
  throw new Error("Kilo token expired — run /login kilo to re-authenticate.");
}

// ─── Models ──────────────────────────────────────────────────────────────────

interface ORModel {
  id: string;
  name: string;
  context_length: number;
  max_completion_tokens?: number | null;
  pricing?: { prompt?: string | null; completion?: string | null; input_cache_read?: string | null; input_cache_write?: string | null };
  architecture?: { input_modalities?: string[] | null; output_modalities?: string[] | null };
  top_provider?: { max_completion_tokens?: number | null };
  supported_parameters?: string[];
}

function price(v: string | null | undefined): number {
  const n = parseFloat(v ?? "0");
  return isNaN(n) ? 0 : n * 1_000_000;
}

function isFree(m: ORModel): boolean {
  const p = parseFloat(m.pricing?.prompt ?? "1");
  const c = parseFloat(m.pricing?.completion ?? "1");
  if (p !== 0 || c !== 0) return false;
  return m.id === "kilo-auto/free" || m.id.includes(":free") || !m.id.includes("/")
      || m.id.startsWith("kilo/") || m.id.startsWith("openrouter/");
}

function modelCompat(m: ORModel): ProviderModelConfig["compat"] | undefined {
  const c: Record<string, unknown> = {
    supportsDeveloperRole: false,
  };
  if (m.id.startsWith("anthropic/")) c.cacheControlFormat = "anthropic";
  if (m.id === "deepseek/deepseek-v4-flash" || m.id === "deepseek/deepseek-v4-pro")
    c.requiresReasoningContentOnAssistantMessages = true;
  if (m.id === "deepseek/deepseek-v4-pro") c.reasoningEffortMap = { xhigh: "max" };
  return c as ProviderModelConfig["compat"];
}

function mapModel(m: ORModel): ProviderModelConfig {
  const inputMods = m.architecture?.input_modalities ?? ["text"];
  const maxTokens = m.top_provider?.max_completion_tokens ?? m.max_completion_tokens ?? Math.ceil(m.context_length * 0.2);
  return {
    id: m.id,
    name: m.name,
    reasoning: m.supported_parameters?.includes("reasoning") ?? false,
    input: inputMods.includes("image") ? ["text", "image"] : ["text"],
    cost: { input: price(m.pricing?.prompt), output: price(m.pricing?.completion), cacheRead: price(m.pricing?.input_cache_read), cacheWrite: price(m.pricing?.input_cache_write) },
    contextWindow: m.context_length,
    maxTokens,
    compat: modelCompat(m),
  };
}

