function mapModel(m: ORModel): ProviderModelConfig {
  const inputMods = m.architecture?.input_modalities ?? ["text"];
  const maxTokens = m.top_provider?.max_completion_tokens ?? m.max_completion_tokens ?? Math.ceil(m.context_length * 0.2);
  return {
    id: m.id,
    name: m.name,
    reasoning: m.supported_parameters?.includes("reasoning") ?? false,
    input: inputMods.includes("image") ? ["text", "image"] : ["text"],
    cost: { input: price(m.pricing?.prompt), output: price(m.pricing?.completion), cacheRead: price(m.pricing?.input_cache_read), cacheWrite: price(m.pricing?.input_cache_write) },
    contextWindow: m.context_length,
    maxTokens,
    compat: modelCompat(m),
  };
}

async function fetchModels(opts: { token?: string; freeOnly?: boolean } = {}): Promise<ProviderModelConfig[]> {
  const headers: Record<string, string> = { "Content-Type": "application/json", "User-Agent": "pi-kilocode-provider/1.0" };
  if (opts.token) headers.Authorization = `Bearer ${opts.token}`;

  const r = await fetchKilo(`${KILO_GATEWAY_BASE}/models`, { headers, timeoutMs: MODELS_TIMEOUT_MS });
  if (!r.ok) throw new Error(`Failed to fetch models: ${r.status} ${r.statusText}`);

  const json = (await r.json()) as { data?: ORModel[] };
  if (!Array.isArray(json.data)) throw new Error("Unexpected models response");

  return json.data
    .filter((m) => {
      if ((m.architecture?.output_modalities ?? []).includes("image")) return false;
      if (opts.freeOnly && !isFree(m)) return false;
      return true;
    })
    .map(mapModel);
}

// ─── Extension Entry Point ────────────────────────────────────────────────────

export default async function (pi: ExtensionAPI) {
  // Load free models up front so provider is usable without login
  let freeModels: ProviderModelConfig[] = [];
  try {
    freeModels = await fetchModels({ freeOnly: true });
  } catch (err) {
    console.warn("[kilocode] Failed to load free models at startup:", (err as Error).message);
  }

  // Full model list populated after login or session_start (when already logged in)
  let allModels: ProviderModelConfig[] = [];
  const startupToken = process.env.KILO_API_KEY || loadStoredToken();
  if (startupToken) {
    try {
      allModels = await fetchModels({ token: startupToken });
    } catch (err) {
      console.warn("[kilocode] Failed to load full models at startup:", (err as Error).message);
    }
  }
  const registeredModels = () => (allModels.length ? allModels : freeModels);

  function buildOAuth() {
    return {
      name: "Kilo",
      login: async (callbacks: OAuthLoginCallbacks) => {
        const cred = await kiloLogin(callbacks);
        try { allModels = await fetchModels({ token: cred.access }); } catch { /* non-fatal */ }
        return cred;
      },
      refreshToken: kiloRefresh,
      getApiKey: (cred: OAuthCredentials) => cred.access,
      modifyModels: (models: Model<Api>[], _cred: OAuthCredentials) => {
        if (!allModels.length) return models;
        const template = models.find((m) => m.provider === "kilo");
        if (!template) return models;
        const rest = models.filter((m) => m.provider !== "kilo");
        return [...rest, ...allModels.map((m) => ({ ...template, ...m }))];
      },
    };
  }

  pi.registerProvider("kilo", { ...PROVIDER_CONFIG, models: registeredModels(), oauth: buildOAuth() });

  // After session starts: pre-fetch full models if already logged in + show credits
  pi.on("session_start", async (_event, ctx) => {
    const cred = ctx.modelRegistry.authStorage.get("kilo");
    const token = cred?.type === "oauth" ? cred.access : process.env.KILO_API_KEY;

    if (!token) {
      ctx.ui.setStatus("kilo-credits", undefined);
      return;
    }

    try {
      allModels = await fetchModels({ token });
      if (allModels.length) {
        ctx.modelRegistry.registerProvider("kilo", { ...PROVIDER_CONFIG, models: registeredModels(), oauth: buildOAuth() });
      }
    } catch (err) {
      console.warn("[kilocode] Failed to load models at session_start:", (err as Error).message);
    }

    if (cred?.type !== "oauth") return;

    try {
      const balance = await fetchBalance(cred.access);
      if (balance !== null) {
        ctx.ui.setStatus("kilo-credits", ctx.ui.theme.fg("accent", `⚡ ${formatCredits(balance)}`));
      }
    } catch { /* non-fatal */ }
  });

  // Refresh credit display after each turn
  pi.on("turn_end", async (_event, ctx) => {
    const cred = ctx.modelRegistry.authStorage.get("kilo");
    if (cred?.type !== "oauth") return;
    try {
      const balance = await fetchBalance(cred.access);
      if (balance !== null) {
        ctx.ui.setStatus("kilo-credits", ctx.ui.theme.fg("accent", `⚡ ${formatCredits(balance)}`));
      }
    } catch { /* non-fatal */ }
  });

  // Show ToS notice on first use without login
  let tosShown = false;
  pi.on("before_agent_start", async (_event, ctx) => {
    if (tosShown || ctx.model?.provider !== "kilo") return;
    const cred = ctx.modelRegistry.authStorage.get("kilo");
    tosShown = true;
    if (cred?.type === "oauth") return;
    return {
      message: {
        customType: "kilo",
        content: `By using Kilo you agree to the Terms of Service: ${KILO_TOS_URL}`,
        display: true,
      },
    };
  });
}

